// P0.8 — shared worker error path. When any workflow execution fails, this
// handler is invoked by n8n's error trigger. It tries to recover the job_id from
// the failed execution's data and, if found, calls fail_job() so the job never
// stays RUNNING forever. If no job_id can be recovered, it emits zero items
// (graceful no-op — the DB lease/max_attempts recovery is the secondary net).
const err = $json || {};
const execution = err.execution || {};
const failed = execution.lastNodeExecuted || '';

// job_id is usually carried in the failed node's item or in the run data.
let jobId = null;
function findJobId(o, depth) {
  if (!o || typeof o !== 'object' || depth > 6) return null;
  if (o.job_id) return o.job_id;
  if (o.jobId) return o.jobId;
  for (const k of Object.keys(o)) {
    if (Array.isArray(o[k])) {
      for (const it of o[k]) { const r = findJobId(it, depth + 1); if (r) return r; }
    } else if (o[k] && typeof o[k] === 'object') {
      const r = findJobId(o[k], depth + 1); if (r) return r;
    }
  }
  return null;
}
jobId = findJobId(err, 0);
if (!jobId) return [];

const errorText = String((err.error && err.error.message) || err.error || 'workflow execution failed');
return [{ json: { jobId: jobId, error: 'WORKFLOW_ERROR:' + failed + ' -> ' + errorText.slice(0, 500) } }];
